<script setup>
import {computed} from 'vue';import {t,number} from '../i18n';import {fabricAreaSummary,shapePoints} from '../../core/fabric-geometry.mjs';
const props=defineProps({lot:{type:Object,required:true},request:Object,wholeReserved:{type:Number,default:0}});const summary=computed(()=>fabricAreaSummary(props.lot,{wholeReserved:props.wholeReserved})),g=computed(()=>props.lot.properties.geometry),m=computed(()=>props.lot.properties.usableMargins??{}),points=shape=>shapePoints(shape).map(([x,y])=>`${x-g.value.offsetXCm},${y-g.value.offsetYCm}`).join(' ');
</script>
<template><section class="form-section"><h3>{{t('fabricMeasuredGeometry')}}</h3><div class="stat-row"><span>{{t('fabricUsableArea')}}</span><strong>{{summary.usableAreaCm2===null?t('unknown'):number(summary.usableAreaCm2,6)+' cm²'}}</strong></div><div class="stat-row"><span>{{t('fabricUnreservedArea')}}</span><strong>{{summary.availableAreaCm2===null?t('unknown'):number(summary.availableAreaCm2,6)+' cm²'}}</strong></div><p class="field-help">{{t('fabricAreaHelp')}}</p><p v-if="!summary.known" class="notice warning">{{t('fabricGeometryUnknown')}}</p><svg v-if="g" width="100%" height="240" :viewBox="`0 0 ${lot.properties.widthCm} ${lot.properties.heightCm}`" role="img" :aria-label="t('fabricGeometryDiagram')"><rect width="100%" height="100%" fill="var(--line)"/><polygon v-if="g.outline" :points="points(g.outline)" fill="var(--surface)" stroke="var(--muted)" stroke-width="1" vector-effect="non-scaling-stroke"/><rect v-else width="100%" height="100%" fill="var(--surface)"/><polygon v-for="(shape,index) in g.defects" :key="index" :points="points(shape)" fill="var(--danger)" fill-opacity=".4" stroke="var(--danger)" stroke-width="1" vector-effect="non-scaling-stroke"/><rect :x="m.left??0" :y="m.top??0" :width="Math.max(0,lot.properties.widthCm-(m.left??0)-(m.right??0))" :height="Math.max(0,lot.properties.heightCm-(m.top??0)-(m.bottom??0))" fill="none" stroke="var(--muted)" stroke-dasharray="2 2" stroke-width="1" vector-effect="non-scaling-stroke"/><rect v-for="region in lot.fabricPlan?.regions.filter(r=>r.status==='active')??[]" :key="region.id" :x="region.xCm" :y="region.yCm" :width="region.widthCm" :height="region.heightCm" fill="var(--accent-soft)" stroke="var(--accent)" stroke-width="2" vector-effect="non-scaling-stroke"/><rect v-if="request" :x="request.xCm" :y="request.yCm" :width="request.widthCm" :height="request.heightCm" fill="none" stroke="var(--ink)" stroke-dasharray="5 3" stroke-width="2" vector-effect="non-scaling-stroke"/></svg><p v-if="g" class="field-help">{{t('fabricGeometryLegend')}}</p></section></template>
